import { notFound } from 'next/navigation';
import type { Metadata } from 'next';
import { articles } from '@/lib/content';
import { ArticleCard, TextLink } from '@/components/ui';
import { ArticleVisual } from '@/components/visuals';
export function generateStaticParams() { return articles.map(a => ({ section:a.section, slug:a.slug })); }
export async function generateMetadata({ params }: { params: Promise<{ section:string; slug:string }> }): Promise<Metadata> { const { section, slug } = await params; const a = articles.find(a => a.slug === slug && a.section === section); return { title:a?.title, description:a?.summary, alternates:{ canonical:`/${section}/${slug}` } }; }
export default async function ArticlePage({ params }: { params: Promise<{ section:string; slug:string }> }) { const { section, slug } = await params; const a = articles.find(a => a.slug === slug && a.section === section); if(!a) notFound(); return <><header className="article-header wrap"><TextLink href={`/${a.section}`}>Back to {a.section === 'tech-blog' ? 'tech blog' : 'news & insights'}</TextLink><h1>{a.title}</h1><p className="intro-description">{a.summary}</p><p className="article-date">{a.category} &nbsp; / &nbsp; <time dateTime={a.date}>{new Date(a.date).toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'})}</time> &nbsp; / &nbsp; {a.minutes} min read</p><ArticleVisual variant={a.visual}/></header><article className="article-body wrap"><p className="article-notice">Illustrative article · Sample editorial content and publication date, prepared for this website. Not a disclosure of proprietary research.</p>{a.paragraphs.map(p => <section key={p.heading}><h2>{p.heading}</h2><p>{p.text}</p></section>)}</article><section className="related wrap"><h2>Keep exploring.</h2><div className="article-grid">{articles.filter(b => b.slug !== a.slug).slice(0,3).map(b => <ArticleCard key={b.slug} article={b}/>)}</div></section></>; }
